    Bug 1842419 - Wait until all messages have been loaded when navigating across folders. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D207576

diff --git a/mail/base/content/mailCommon.js b/mail/base/content/mailCommon.js
index a1b07fe3b85..506dbf7dbc1 100644
--- a/mail/base/content/mailCommon.js
+++ b/mail/base/content/mailCommon.js
@@ -875,9 +875,7 @@ var commandController = {
       );
       addedRowsByViewNavigate = gViewWrapper.dbView.rowCount - countBefore;
       if (resultIndex.value == nsMsgViewIndex_None) {
-        if (CrossFolderNavigation(navigationType)) {
-          this._navigate(navigationType);
-        }
+        CrossFolderNavigation(navigationType, this._navigate);
         return;
       }
       if (resultKey.value == nsMsgKey_None) {
@@ -1090,6 +1088,9 @@ var dbViewWrapperListener = {
       if (!newMessageFound && !window.threadPane.scrollDetected) {
         window.threadPane.scrollToLatestRowIfNoSelection();
       }
+      if (all) {
+        window.dispatchEvent(new CustomEvent("allMessagesLoaded"));
+      }
     }
     // To be consistent with the behavior in saved searches, update the message
     // count in synthetic views when a quick filter term is entered or cleared.
diff --git a/mail/base/content/msgViewNavigation.js b/mail/base/content/msgViewNavigation.js
index be65f9e6b9a..92dab77f151 100644
--- a/mail/base/content/msgViewNavigation.js
+++ b/mail/base/content/msgViewNavigation.js
@@ -128,14 +128,20 @@ function GetRootFoldersInFolderPaneOrder() {
   return serversMsgFolders;
 }

+/**
+ * @callback navigateCallback
+ * @param {nsMsgNavigationType} type - The type of navigation.
 /**
  * Handle switching the folder if required for the given kind of navigation.
  * Only used in about:3pane.
  *
  * @param {nsMsgNavigationType} type - The type of navigation.
+ * @param {navigateCallback} [navigateFunction] - The function to be called
+ *   when the folder has been changed and all messages in that folder have been
+ *   loaded. This is `commandController._navigate`.
  * @returns {boolean} If the folder was changed for the navigation.
  */
-function CrossFolderNavigation(type) {
+function CrossFolderNavigation(type, navigateFunction) {
   // do cross folder navigation for next unread message/thread and message history
   if (
     type != Ci.nsMsgNavigationType.nextUnreadMessage &&
@@ -188,6 +194,9 @@ function CrossFolderNavigation(type) {

   if (window.threadPane) {
     // In about:3pane.
+    window.addEventListener("allMessagesLoaded", () => navigateFunction(type), {
+      once: true,
+    });
     window.threadPane.forgetSelection(folder.URI);
     window.displayFolder(folder.URI);
   } else {
@@ -201,6 +210,7 @@ function CrossFolderNavigation(type) {
     selection.view = gDBView;
     // We're now in a bit of a weird state until `displayMessage` is called,
     // but being here means we have everything we need for that to happen.
+    navigateFunction(type);
   }
   return true;
 }
